def literal_continuations(s):
    if r'\widehat{i_p}' in s:
        s=s.replace(r'\Sigma_{i_0\ldots i_n}',r'\Sigma_{i_0-\, -i_n}')
        s=s.replace(r'\Sigma_{i_0\ldots\widehat{i_p}\ldots i_n}',r'\Sigma_{i_0-\widehat{i_p}-\, -i_n}')
    else:
        s=s.replace(r'\Sigma_{i_0\ldots i_n}',r'\Sigma_{i_0-i_n}')
    s=s.replace(r'\le\cdots\le',r'\le -\, -\le')
    s=s.replace(r'\cap\cdots',r'\cap -\, -')
    s=s.replace(r'\(i_0,\ldots i_n\)',r'\(i_0,-i_n\)')
    s=s.replace(r'\{i_0,\ldots i_n\}',r'\{i_0,\unsure{-}i_n\}')
    return s

